import React, { useState } from "react";
import "./Styles/main.css";
import Animations from "./Animation";

//===---Components
import NavBar from "./Components/NavBar";
import Home from "./Components/Home";
import About from "./Components/About";
import Work from "./Components/Work"
import Skills from "./Components/Skills";
import Experiences from "./Components/Experiences"
import Contact from "./Components/Contact";

export default function App(){
    Animations();

    const [darkModeSettings, setDarkModeSettings] = useState({
        mode: "0",
        transition: "transform 1s ease-in-out",
        filter: "brightness(1)"
    })
    var transitionStyle = {transition: darkModeSettings.transition};
    var opacityStyle = {opacity: darkModeSettings.mode};
    var filterStyle = {filter: darkModeSettings.filter}

    const modeToggle = event => {
        var sunMoon = document.querySelector(".celestialBodies");
        
        event.currentTarget.classList.toggle("active");
        document.querySelector("#app").classList.toggle("dark");
        sunMoon.classList.toggle("toggle");
        
        if (event.currentTarget.classList.contains("active")) {
            setDarkModeSettings({
                mode: "1",
                transition: "transform 1s ease-in-out",
                filter: "brightness(0.75)"
            });
        } else {
            setDarkModeSettings( (prevSettings) => ({
                ...prevSettings,
                mode: "0",
                filter: "brightness(1)"
            }));
            sunMoon.classList.add("transition");
            setTimeout( () => {
                setDarkModeSettings( (prevSettings) => ({
                    ...prevSettings,
                    transition: ""
                }));
                ;sunMoon.classList.remove("transition");
            }, 1000);
        }
    }

    return(
        <div id="app">
            <header id="header">
                <div className="indicator"></div>
                <NavBar 
                    clickHandle={modeToggle}
                />
            </header>
            <main>
                <Home 
                    opacityStyle={opacityStyle}
                    transitionStyle={transitionStyle}
                />
                <About />
                <Work />
                <Skills />
                <Experiences
                    opacityStyle={opacityStyle}
                 />
            </main>
            <footer>
                <Contact
                    opacityStyle={opacityStyle}
                    filterStyle={filterStyle}
                />
            </footer>
        </div>
    )
}