import React from "react";
import SkillCard from "./Sub_components/SkillCard";
import skillsData from "./Data/SkillsData";
import { IoChevronDownOutline } from "react-icons/io5";

export default function Skills() {

    const section = skillsData.map( ( {img, title} ) => {
        return(
            <SkillCard 
                key={title}
                img={img}
                title={title}
            />
    )})

    function expandGrid() {
        const grid = document.querySelector(".skills-grid");
        const btn = document.querySelector(".expand-btn");

        if(grid.classList.contains("active")) {
            grid.classList.remove("active");
            btn.classList.remove("active");
            btn.firstChild.innerHTML = "EXPAND";
        } else {
            grid.classList.add("active");
            btn.classList.add("active");
            btn.firstChild.innerHTML = "CLOSE";
        }
    }
    
    return(
        <section id="skills">
            <div className="skills-container">
                <div className="skills-header">
                    <h3 className="skills-title text">MY SKILLS</h3>
                    <p className="skills-desc text">My ever-growing skill set.</p>
                </div>
                <div className="skills-grid">
                    {section}
                </div>
                <button className="expand-btn" onClick={expandGrid}>
                        <span>EXPAND</span>
                        <span><IoChevronDownOutline /></span>
                </button>
            </div>
        </section>
    )
}