import React from "react";
import ExpCard from "./Sub_components/ExpCard";
import ExpData from "./Data/ExpData";
import { IoChevronDownOutline } from "react-icons/io5";

export default function Experiences(props) {

    const section = ExpData.map( ( { img, link, title, date, subTitle, desc } ) => {
        return(
            <ExpCard 
                key={title}
                img={img}
                link={link}
                title={title}
                date={date}
                subTitle={subTitle}
                desc={desc}
            />
    )})

    function expandGrid() {
        const grid = document.querySelector(".exp-grid");
        const btn = document.querySelector(".expand-exp-btn");

        if(grid.classList.contains("active")) {
            grid.classList.remove("active");
            btn.classList.remove("active");
            btn.firstChild.innerHTML = "EXPAND";
        } else {
            grid.classList.add("active");
            btn.classList.add("active");
            btn.firstChild.innerHTML = "CLOSE";
        }
    }

    return (
        <section id="exp">
            <div className="exp-container">
                <div className="exp-header">
                    <h3 className="exp-title text">MY EXPERIENCES</h3>
                    <p className="exp-desc text">Locations I've worked for so far.</p>
                </div>
                <div className="exp-grid">
                    {section}
                </div>
                <button className="expand-btn expand-exp-btn" onClick={expandGrid}>
                        <span>EXPAND</span>
                        <span><IoChevronDownOutline /></span>
                </button>
            </div>
        </section>
    )
}