import React from "react";
import WorkCard from "./Sub_components/WorkCard";
import WorkData from "./Data/WorkData";

export default function Work() {

    const section = WorkData.map( ( { img, link, title, date, desc, altDesc } ) => {
        return(
            <WorkCard 
                key={title}
                img={img}
                link={link}
                title={title}
                date={date}
                desc={desc}
                altDesc={altDesc}
            />
    )})

    return(
        <section id="projects">
        <div className="work-container">
            <div className="work-header">
                <h3 className="work-title text">MY PROJECTS</h3>
                <p className="work-desc text">Projects I've worked on so far.</p>
            </div>
            <div className="work-grid">
                {section}
            </div>
        </div>
    </section>
    );
}