import React, { useState } from "react";
import { gsap } from "gsap";
import emailjs from "emailjs-com";

//===--- Imgs
import dayShape from "../Images/Shapes/shape1.webp";
import nightShape from "../Images/Shapes/shape1Dark.webp";
import mailBack from "../Images/Landscape/mailBack.webp";
import mailFrontOpened from "../Images/mailFront_Opened.webp";
import mailFrontClosed from "../Images/mailFront_Closed.webp";
import stars from "../Images/Celestial-Bodies/stars.webp";

//===--- Icons
import { AiOutlineMail, AiFillLinkedin, AiFillGithub } from "react-icons/ai";
import { BsCheckLg } from "react-icons/bs";
import { ImCross } from "react-icons/im";

export default function Contact(props) {
    //Bottom Parallax
    window.addEventListener("scroll", () => {
        var aboutPos = document.querySelector("#skills").offsetTop;

        if (window.scrollY >= (aboutPos)) {
            var value = window.pageYOffset - (document.body.scrollHeight - window.innerHeight);

            document.querySelector(".landscape").style.bottom = value * -0.15 + "px";

            document.querySelector(".mail-box-open").style.bottom = value * -0.3 + "px";
            document.querySelector(".mail-box-closed").style.bottom = value * -0.3 + "px";
            
            document.querySelector(".con-stars-img").style.bottom = value * 0.2 + "px";
        }
    })

    const [contactStyles, setcontactStyles] = useState({
        show: "1",
        noShow: "0",
        success: false,
        fail: false,
        fail2: false
    })

    const [formData, setFormData] = useState({
        name: "",
        email: "",
        subject: "",
        message: ""
    })

    function handleChange(event) { 
        setFormData(prevFormData => {
            return {
                ...prevFormData,
                [event.target.name]: event.target.value
            }
        })
    }

    function handleSubmit(event) {
        event.preventDefault();
        let name = document.querySelector(".name");
        let email = document.querySelector(".email");
        let subject = document.querySelector(".subject");
        let message = document.querySelector(".message");
 
        //Check if all fields are filled and email is valid
        if (
            formData.name.length >= 1 &&
            formData.email.length >= 1 &&
            formData.subject.length >= 1 &&
            formData.message.length >= 1 &&
            formData.email.includes("@")
        ) {
            setcontactStyles( prevStyle => {
                return{
                    ...prevStyle,
                    show: "0",
                    noShow: "1",
                    success: true
                }
            })
            //Change border color to success green
            name.classList.add("success")
            email.classList.add("success")
            subject.classList.add("success")
            message.classList.add("success")
            //Send email
            emailjs.sendForm('service_email', 'template_veclmwh', event.target, '9Pqk6uYwgA_txHoVR')
            .then((result) => {
                console.log(result.text);
            }, (error) => {
                console.log(error.text);
            });
            event.target.reset();
        } else {
            //Change border color to fail red
            if (formData.name.length < 1) {
                name.classList.add("fail");
            } else {
                name.classList.add("success");
            };
            if (formData.email.length < 1 || !formData.email.includes("@")) {
                email.classList.add("fail");
            } else {
                email.classList.add("success");
            };
            if (formData.subject.length < 1) {
                subject.classList.add("fail");
            } else {
                subject.classList.add("success");
            };
            if (formData.message.length < 1) {
                message.classList.add("fail");
            } else {
                message.classList.add("success");
            };
            if (
                name.classList.contains("success") &&
                subject.classList.contains("success") &&
                message.classList.contains("success") &&
                !formData.email.includes("@")
            ) {
                setcontactStyles( prevStyle => {
                    return{
                        ...prevStyle,
                        fail: false,
                        fail2: true
                    }
                })
            } else {
                setcontactStyles( prevStyle => {
                    return{
                        ...prevStyle,
                        fail: true,
                        fail2: false
                    }
                })
            }
        }
        
        //Success animation
        setTimeout( () => {
            gsap.to(".sent", {
                opacity: 0,
                ease: "power2.out",
                duration: 1
            })
            //Change border color back to original
            name.classList.remove("success", "fail")
            email.classList.remove("success", "fail")
            subject.classList.remove("success", "fail")
            message.classList.remove("success", "fail")
        }, 4000);
        setTimeout( () => {
            setcontactStyles( prevStyle => {
                return{
                    ...prevStyle,
                    success: false,
                    fail: false,
                    fail2: false
                }
            })
        }, 5000);
    }

    var colorStyle = {color: "#FC100D"};
    var opacityStyle1 = {opacity: contactStyles.show};
    var opacityStyle2 = {opacity: contactStyles.noShow};

    return(
        <section id="contact">
            {//<div className="divider"></div> Line that divides components
            }
            <div className="contact-container">
                <div className="contact-header">
                    <h3 className="contact-title text">GET IN TOUCH</h3>
                </div>
                <div className="contact-body">
                    <div className="contact-imgs">
                        <div className="nightGradient" style={props.opacityStyle}></div>
                        <img src={dayShape} alt="A wide white U-like shape" className="dayShape"></img>
                        <img src={nightShape} alt="A wide grey U-like shape" className="nightShape" style={props.opacityStyle}></img>
                        <img src={mailBack} alt="Post Office on a hill" className="landscape" style={props.filterStyle}></img>
                        <img src={stars} alt="Stars" className="con-stars-img" style={props.opacityStyle}></img>
                        {/*===--- Opened ---===*/}
                        <img src={mailFrontOpened} alt="Opened mail box" className="mail-box-open" style={Object.assign({}, props.filterStyle, opacityStyle1)}></img> 
                        {/*===--- Closed ---===*/}
                        <img src={mailFrontClosed} alt="Closed mail box" className="mail-box-closed" style={Object.assign({}, props.filterStyle, opacityStyle2)}></img>
                    </div>
                    <div className="contacts-form">
                        {contactStyles.success && <h2 className="sent">Successfully sent<BsCheckLg className="icon"/></h2>}
                        {contactStyles.fail && <h2 className="sent" style={colorStyle}>All areas must be filled<ImCross className="icon"/></h2>}
                        {contactStyles.fail2 && <h2 className="sent" style={colorStyle}>Invalid Email<ImCross className="icon"/></h2>}
                        <form className="form" onSubmit={handleSubmit}>
                            <div className="common">
                                <label> Name:
                                    <input 
                                        type="text"
                                        onChange={handleChange}
                                        name="name"
                                        value={formData.name}
                                        className="name"
                                    />
                                </label>
                                <label> Email:
                                    <input 
                                        type="text"
                                        onChange={handleChange}
                                        name="email"
                                        value={formData.email}
                                        className="email"
                                    />
                                </label>
                            </div>
                            <label> Subject:
                                <input 
                                    type="text"
                                    onChange={handleChange}
                                    name="subject"
                                    value={formData.subject}
                                    className="subject"
                                />
                            </label>
                            <label> Message:
                                <textarea 
                                    onChange={handleChange}
                                    name="message"
                                    value={formData.message}
                                    className="message"
                                />
                            </label>
                            <button className="submit-btn">SUBMIT</button>
                        </form>
                        <ul className="contact-list">
                            <li className="cList">
                                <a href="mailto:aguayo.jesus2003@gmail.com">
                                    <AiOutlineMail />
                                    <span>Email</span>
                                </a>
                            </li>
                            <li className="cList">
                                <a href="https://www.linkedin.com/in/jesus-aguayo/" target="_blank" rel="noreferrer">
                                    <AiFillLinkedin />
                                    <span>Linked In</span>
                                </a>
                            </li>
                            <li className="cList">
                                <a href="https://github.com/jesus-404" target="_blank" rel="noreferrer">
                                    <AiFillGithub />
                                    <span>Github</span>
                                </a>
                            </li>
                        </ul>
                    </div>
                </div>
            </div>
        </section>
    )
}