import React from "react";
import { MdOutlineFileDownload } from "react-icons/md";
import DOWNLOAD from "../Resume.pdf";

import profPic from "../Images/prof_pic_small.webp"

export default function About() {

    document.addEventListener("DOMContentLoaded", () => {
        function flipCheck(el) {
            if(checkVisible(el)) {el.classList.add("reveal")}
        }
        function checkVisible(elm) {
            var rect = elm.getBoundingClientRect();
            var viewHeight = Math.max(document.documentElement.clientHeight, window.innerHeight);

            return !(rect.bottom < 0 || rect.top - viewHeight >= 0);
        }

        window.addEventListener("scroll", () => {flipCheck(document.querySelector(".about-body"))})
    })

    return (
        <section id="about">
            <div className="about-container">
                <div className="about-header">
                    <h3 className="about-title">ABOUT</h3>
                </div>
                <div className="about-body">
                    <img src={profPic} alt="A picure of me" className="prof-pic"></img>
                    <span className="about-text">
                        <h4 className="about-subTitle">Once again, Hello!</h4>
                        <p className="about-paragraph">I’m Jesus Aguayo, a current student at
                        CSU East Bay majoring in Computer Science 
                        and future aspiring Full-Stack Web Developer.
                        I’ve worked as a team leader and instructor 
                        revolving all about programming. 
                        I am confident and able to use 
                        my current skills for the benefit of your company. 
                            <button className="about-btn">
                                <a href={DOWNLOAD} download="Resume">
                                    <span>DOWNLOAD RESUME</span>
                                    <span><MdOutlineFileDownload /></span>
                                </a>
                            </button>
                        </p>
                    </span>
                </div>
            </div>
        </section>
    )
}

