import React, { useState } from "react";
import { IoSunny, IoMoon } from "react-icons/io5";
import gsap from "gsap";

export default function NavBarHome(props) {

    //===--- Nav-Bar
    
    document.addEventListener("DOMContentLoaded", () => {

        //===--- Stick Nav-Bar

        var navbar = document.querySelector("#header");
        var aboutPos = document.querySelector("#about").offsetTop;
        var navbarPos = document.querySelector("#about").offsetTop;

        function navbarStickMax() {
            if (window.pageYOffset >= (aboutPos - 5)) {
                navbar.classList.add("sticky");
                document.querySelector(".indicator").classList.add("sticky");

                gsap.to(navbar, {
                    y: "100px",
                    backgroundColor: "var(--sG)",
                    ease: "expo.out",
                    duration: .5
                });
            } else {
                gsap.to(navbar, {
                    y: "0px",
                    backgroundColor: "transparent",
                    ease: "expo.out",
                    duration: .5
                });
                if(window.pageYOffset <= (aboutPos - 100)) {
                    navbar.classList.remove("sticky");
                    document.querySelector(".indicator").classList.remove("sticky");
                }
            }
        } 
        function navbarStickMin() {
            navbar.classList.add("sticky");
            document.querySelector(".indicator").classList.add("sticky");
            
            if (window.pageYOffset >= (navbarPos - 100)) {
                gsap.to(navbar, {
                    backgroundColor: "var(--sG)",
                    ease: "circ.out",
                    duration: .1
                });
            } else {
                gsap.to(navbar, {
                    y: "100px",
                    duration: 0
                });
                gsap.to(navbar, {
                    backgroundColor: "transparent",
                    ease: "circ.out",
                    duration: .1
                });
            }
        } 
        window.addEventListener("scroll", () => {
            window.innerWidth > 1024 ? navbarStickMax() : navbarStickMin();
        })
    })

    //===--- Set indicator
    
    function resizeIndicator(shift) {
        let indicator = document.querySelector(".indicator");
        let position = document.querySelector(".active").getBoundingClientRect();

        indicator.style.left = position.left + shift + "px";
        indicator.style.width = position.width + "px";
        indicator.style.transition = "";
    }
    
    function setIndicator(currentTarget) {
        let indicator = document.querySelector(".indicator");
        let position = currentTarget.getBoundingClientRect();
    
        indicator.style.left = position.left + "px";
        indicator.style.width = position.width + "px";
        indicator.style.transition = "left .4s ease-in-out, width .4s ease-in-out";
    }

    function menuFix() {
        document.querySelector(".hamburger-menu").classList.remove("active");
        document.querySelector(".ulist").classList.remove("toggle");
        document.querySelector(".menu-lines").classList.remove("active");
        setZIndex( (prevIndex) => prevIndex = "19");
    }
    
    window.addEventListener("resize", () => resizeIndicator(0) );
    window.addEventListener("load", () => resizeIndicator(0) );

    window.addEventListener("resize", () => {
        if(window.innerWidth > 1024){menuFix()};
    });
    
    //===---Class name change

    const [zIndex, setZIndex] = useState("19");
    var zIndexStyle = {zIndex: zIndex};

    const menuToggle = event => {
        event.currentTarget.classList.toggle("active");
        document.querySelector(".ulist").classList.toggle("toggle");
        document.querySelector(".menu-lines").classList.toggle("active");
        zIndex === "19" ? setZIndex( (prevIndex) => prevIndex = "23") : setZIndex( (prevIndex) => prevIndex = "19");
    }

    const listToggle = event => {
        document.querySelectorAll(".list").forEach(item =>
        item.classList.remove("active"));
        event.currentTarget.classList.add("active");
        setIndicator(event.currentTarget);
    }

    //Change active based on section
    document.addEventListener("DOMContentLoaded", () => {
        const section = document.querySelectorAll("section");

        window.addEventListener("scroll", () => {  
            let current = "";
            let scrollPos = window.pageYOffset;

            section.forEach( section => {
                const sectionTop = section.offsetTop;
                const sectionHeight = section.clientHeight;

                if(scrollPos >= (sectionTop - sectionHeight / 3)) {
                    current = section.getAttribute("id");
                }
            })
            document.querySelectorAll(".list").forEach(item => {
                item.classList.remove("active");
                if(item.classList.contains(current)) {
                    item.classList.add("active");
                    setIndicator(item);
                }
            });
        });
    });

    return(
        <section id="nav-bar" style={zIndexStyle}>
            <nav className="navigation">
                <div className="hamburger-menu" onClick={menuToggle}>
                    <div className="menu-lines"></div>
                </div>
                <ul className="ulist">
                    <li className="home list active" onClick={listToggle}>
                        <a href="#home">
                            <span className="nav-text">HOME</span>
                        </a>
                    </li>
                    <li className="about list" onClick={listToggle}>
                        <a href="#about">
                            <span className="nav-text">ABOUT</span>
                        </a>
                    </li>
                    <li className="projects list" onClick={listToggle}>
                        <a href="#projects">
                            <span className="nav-text">PROJECTS</span>
                        </a>
                    </li>
                    <li className="skills list" onClick={listToggle}>
                        <a href="#skills">
                            <span className="nav-text">SKILLS</span>
                        </a>
                    </li>
                    <li className="exp list" onClick={listToggle}>
                        <a href="#exp">
                            <span className="nav-text">EXPERIENCES</span>
                        </a>
                    </li>
                    <li className="contact list" onClick={listToggle}>
                        <a href="#contact">
                            <span className="nav-text">CONTACT</span>
                        </a>
                    </li>
                    <li className="mode" onClick={props.clickHandle}>
                        <IoSunny className="sun-icon"/>
                        <IoMoon className="moon-icon"/>
                    </li>
                </ul>
            </nav>
        </section>
    )
};