import { useEffect } from "react";
import gsap from "gsap";

export default function Animations() {
    useEffect( () => {
        let timeDuration = 1;
        let timeDelay = 1;
        let easeShape = "expo.out";
        let easeText = "back.out(1.5)";
        
        gsap.from(".dayShape", {
            bottom: '100%',
            ease: easeShape,
            duration: timeDuration,
            delay: timeDelay
        })
        gsap.to(".white-block", {
            height: '0%',
            ease: easeShape,
            duration: timeDuration,
            delay: timeDelay
        })
        gsap.from("#header", {
            y: '-100px',
            opacity: 0,
            ease: easeText,
            duration: timeDuration,
            delay: timeDelay
        })
        gsap.from(".home-container1", {
            y: '100px',
            opacity: 0,
            ease: easeText,
            duration: timeDuration,
            delay: timeDelay
        })
    }, [])
}