import React from "react";
import { IoChevronForwardOutline } from "react-icons/io5";

/*===---Other Images---=== */
import sun from "../Images/Celestial-Bodies/sun.webp";
import moon from "../Images/Celestial-Bodies/moon.webp";
import cloud from "../Images/cloud1.webp";
import stars from "../Images/Celestial-Bodies/stars.webp";

/*===---Day Images---=== */
import dayShape from "../Images/Shapes/shape1.webp";
import frontDay from "../Images/Landscape/fontHouse1_Day.webp";
import backDay from "../Images/Landscape/backround_Day.webp";

/*===---Night Images---=== */
import nightShape from "../Images/Shapes/shape1Dark.webp";
import frontNight from "../Images/Landscape/frontHouse1_Night.webp";
import backNight from "../Images/Landscape/backround_Night.webp";

export default function Home(props) {

    //Parallax
    window.addEventListener("scroll", () => {
        var value = window.scrollY;

        document.querySelector(".front-Day").style.bottom = value * -0.05 + "px";
        document.querySelector(".front-Night").style.bottom = value * -0.05 + "px";

        document.querySelector(".back-Day").style.bottom = value * -0.1 + "px";
        document.querySelector(".back-Night").style.bottom = value * -0.1 + "px";
        
        document.querySelector(".stars-img").style.bottom = value * 0.2 + "px";
    })

    return (
        <section id="home">
            <div className="backround-imgs">
                <div className="all-imgs">
                    <div className="nightGradient" style={props.opacityStyle}></div>
                    {/*===---Other Images---=== */}
                    <span className="celestialBodies" style={props.transitionStyle}>
                        <img src={sun} rel="preload" alt="Sun" className="sun-img"></img>
                        <img src={moon} alt="Moon" className="moon-img" style={props.transitionStyle}></img>
                    </span>
                    <img src={cloud} rel="preload" alt="Cloud" className="cloud-img"></img>
                    <img src={stars} alt="Stars" className="stars-img" style={props.opacityStyle}></img>
                    <div className="white-block"></div>
                    {/*===---Day Images---=== */}
                    <img src={dayShape} rel="preload" alt="A wide white U-like shape" className="dayShape"></img>
                    <img src={frontDay} rel="preload" alt="House on the hill" className="front-Day"></img>
                    <img src={backDay} rel="preload" alt="Houses on a hill" className="back-Day"></img>
                    {/*===---Night Images---=== */}
                    <img src={nightShape} alt="A wide grey U-like shape" className="nightShape" style={props.opacityStyle}></img>
                    <img src={frontNight} alt="House on the hill" className="front-Night" style={props.opacityStyle}></img>
                    <img src={backNight} alt="Houses on a hill" className="back-Night" style={props.opacityStyle}></img>
                </div>
            </div>
            <div className="home-container1">
                <div className="home-container2">
                    <div className="home-text">
                        <h2>Hello, My name is...</h2>
                        <h1>Jesus Aguayo</h1>
                        <h2>...an aspiring Web Developer</h2>
                        <a className="home-btn" href="#projects">
                            <span>VIEW PROJECTS</span>
                            <span><IoChevronForwardOutline /></span>
                        </a>
                    </div>
                </div> 
            </div>
        </section>
    )
}