import React from "react";

export default function WorkCard(props) {

        document.addEventListener("DOMContentLoaded", () => {
            function flipCheck(el) {
                el.forEach(item => {
                    if(checkVisible(item)) {item.classList.add("reveal")}
                })
            }
        function checkVisible(elm) {
            var rect = elm.getBoundingClientRect();
            var viewHeight = Math.max(document.documentElement.clientHeight, window.innerHeight);

            return !(rect.bottom < 0 || rect.top - viewHeight >= 0);
        }

        window.addEventListener("scroll", () => {flipCheck(document.querySelectorAll(".work-card"))})
    })

    return (
        <a className="work-card" href={props.link} target="_blank" rel="noreferrer">
            <img src={props.img} alt={props.altDesc} loading="lazy"></img>
            <span className="card-text">
                <h4>{props.title}</h4>
                <p>{props.date}</p>
                <p>{props.desc}</p>
            </span>
        </a>
    )
}