import React from "react";

export default function ExpCard(props) {
    document.addEventListener("DOMContentLoaded", () => {
        function flipCheck(el) {
            el.forEach(item => {
                if(checkVisible(item)) {item.classList.add("reveal")}
            })
        }

        function checkVisible(elm) {
            var rect = elm.getBoundingClientRect();
            var viewHeight = Math.max(document.documentElement.clientHeight, window.innerHeight);

            return !(rect.bottom < 0 || rect.top - viewHeight >= 0);
        }

        window.addEventListener("scroll", () => {flipCheck(document.querySelectorAll(".exp-card"))});
    })

    return (
        <div id={props.title} className="exp-card">
            <img src={props.img} alt={props.title} loading="lazy"></img>
            <span className="card-text1">
                <h4>{props.title}</h4>
                <p>{props.date}</p>
            </span>
            <span className="dot">
                <span className={`dash ${props.title}`}></span>
            </span>
            <span className="card-text2">
                <h5>{props.subTitle}</h5>
                <p>{props.desc}</p>
            </span>
        </div>
    )
}